import streamlit as st

st.title("chai Taste poll")
col1,col2=st.columns(2)
with col1:
    st.header("Masala Chai")
    st.image("data:image/jpeg;base64,",width=200)
    vote1=st.button("vote masala chai")
with col2:
    st.header("Adarak Chai")
    st.image("data:image/jpeg;base64,",width=200)
    vote2=st.button("vote adarak chai")

if vote1:
    st.success("Greate you vote for Masala chai ")
elif vote2:
    st.success("Greate you vote for Adarak chai ")

st.sidebar.write("Home page")

name=st.sidebar.text_input("Enter your name ")
if name:
    st.sidebar.markdown(f'### Hello {name}')

with st.expander("Instruction of making tea"):
    st.write(""" 
    1.boil water
    \n2.add tea leaf and sugar 
\n3.add milk
""")
